"""
Run this once to write the fixed discovery.html directly -- fixes the
Force rescan / Show all links incorrectly triggering a brand search
for upload results, and adds xlsx support + a force_rescan option to
the upload form. Delete this file afterwards if you like.
"""

content = '{% extends "base.html" %}\n\n{% block title %}Discovery - Atlas{% endblock %}\n\n{% block content %}\n\n<div class="card metric p-4 mb-4">\n    <form method="get" action="/discovery" class="row g-3 align-items-end">\n        <div class="col-md-4">\n            <label class="form-label">Brand</label>\n            <input type="text" class="form-control" name="brand" value="{{ brand }}" placeholder="e.g. philips" required>\n        </div>\n        <div class="col-md-2">\n            <label class="form-label">Max ASINs to scan</label>\n            <input type="number" class="form-control" name="limit" value="{{ limit }}" min="1" max="500">\n        </div>\n        <div class="col-md-3">\n            <label class="form-label">Results</label>\n            <select class="form-select" name="profitable_only">\n                <option value="true" {{ "selected" if profitable_only }}>Only profitable</option>\n                <option value="false" {{ "selected" if not profitable_only }}>Show all</option>\n            </select>\n        </div>\n        <div class="col-md-3">\n            <button type="submit" class="btn btn-dark w-100">\n                <i class="bi bi-search"></i> Scan for opportunities\n            </button>\n        </div>\n    </form>\n</div>\n\n<div class="card metric p-4 mb-4">\n    <div class="text-muted small mb-2">Or upload a list of ASINs to scan directly (.txt, .csv, or .xlsx -- one per line/row, or any column)</div>\n    <form method="post" action="/discovery/upload" enctype="multipart/form-data" class="row g-3 align-items-end">\n        <div class="col-md-3">\n            <label class="form-label">File</label>\n            <input type="file" class="form-control" name="file" accept=".txt,.csv,.xlsx,.xls" required>\n        </div>\n        <div class="col-md-3">\n            <label class="form-label">Label (optional)</label>\n            <input type="text" class="form-control" name="list_name" placeholder="e.g. supplier list July">\n        </div>\n        <div class="col-md-2">\n            <label class="form-label">Max ASINs</label>\n            <input type="number" class="form-control" name="limit" value="200" min="1" max="2000">\n        </div>\n        <div class="col-md-2">\n            <label class="form-label">Results</label>\n            <select class="form-select" name="profitable_only">\n                <option value="true" selected>Only profitable</option>\n                <option value="false">Show all</option>\n            </select>\n        </div>\n        <div class="col-md-2">\n            <label class="form-label">Rescan</label>\n            <select class="form-select" name="force_rescan">\n                <option value="false" selected>Skip recent (default)</option>\n                <option value="true">Force rescan all</option>\n            </select>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-outline-dark w-100">\n                <i class="bi bi-upload"></i> Upload &amp; scan\n            </button>\n        </div>\n    </form>\n</div>\n\n{% if result %}\n\n    {% if asins_found_in_upload is defined %}\n        <div class="alert alert-light border">\n            <i class="bi bi-file-earmark-check"></i>\n            Found {{ asins_found_in_upload }} ASIN{{ "s" if asins_found_in_upload != 1 }} in the uploaded file.\n        </div>\n    {% endif %}\n\n    {% if result.error %}\n        <div class="alert alert-warning">\n            <i class="bi bi-exclamation-triangle"></i> {{ result.error }}\n        </div>\n    {% else %}\n\n        <div class="row mb-4">\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Opportunities found</div>\n                    <h2>{{ result.count }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Excluded (category/brand/ASIN)</div>\n                    <h2>{{ result.skipped_excluded }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Keepa tokens remaining</div>\n                    <h2>{{ result.tokens_remaining if result.tokens_remaining is not none else "?" }}</h2>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card metric p-3 text-center">\n                    <div class="text-muted small">Marketplaces skipped (low tokens)</div>\n                    <h2>{{ result.marketplaces_skipped_low_tokens | length }}</h2>\n                </div>\n            </div>\n        </div>\n\n        {% if result.skipped_recently_scanned %}\n            <div class="alert alert-secondary">\n                <i class="bi bi-clock-history"></i>\n                Skipped {{ result.skipped_recently_scanned }} product{{ "s" if result.skipped_recently_scanned != 1 }} already scanned in the last 24h (saves tokens).\n                {% if is_upload %}\n                    Re-upload the file with "Force rescan" enabled to check them again.\n                {% else %}\n                    <a href="/discovery?brand={{ brand }}&limit={{ limit }}&profitable_only={{ profitable_only|lower }}&force_rescan=true">Force rescan everything</a>\n                {% endif %}\n            </div>\n        {% endif %}\n\n        {% if hidden_count %}\n            <div class="alert alert-secondary">\n                <i class="bi bi-eye-slash"></i>\n                {{ hidden_count }} unprofitable result{{ "s" if hidden_count != 1 }} hidden.\n                {% if is_upload %}\n                    Re-upload the file with "Show all" selected to see them.\n                {% else %}\n                    <a href="/discovery?brand={{ brand }}&limit={{ limit }}&profitable_only=false">Show all</a>\n                {% endif %}\n            </div>\n        {% endif %}\n\n        {% if result.marketplaces_skipped_low_tokens %}\n            <div class="alert alert-info">\n                <i class="bi bi-info-circle"></i>\n                Skipped {{ result.marketplaces_skipped_low_tokens | join(", ") }} for some/all ASINs due to low token budget.\n            </div>\n        {% endif %}\n\n        {% if result.opportunities %}\n        <div class="card metric p-3">\n            <div class="table-responsive">\n                <table class="table table-hover align-middle">\n                    <thead>\n                        <tr>\n                            <th>Product</th>\n                            <th>Best Source</th>\n                            <th>Source Cost</th>\n                            <th>UK Price</th>\n                            <th>Profit</th>\n                            <th>ROI</th>\n                            <th>Score</th>\n                            <th>Confidence</th>\n                            <th>Recommendation</th>\n                            <th></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        {% for o in result.opportunities %}\n                        {% set p = o.product %}\n                        {% set r = o.report %}\n                        <tr>\n                            <td style="max-width:320px;">\n                                <div class="fw-semibold small">{{ p.title[:80] }}{% if p.title|length > 80 %}...{% endif %}</div>\n                                <div class="text-muted small">{{ p.asin }} &middot; {{ p.brand }}</div>\n                            </td>\n                            <td>{{ p.best_source_marketplace }}</td>\n                            <td>&pound;{{ "%.2f"|format(p.best_source_cost_gbp) }}</td>\n                            <td>&pound;{{ "%.2f"|format(p.buy_box_now) }}</td>\n                            <td class="{{ \'text-success\' if p.profit > 0 else \'text-danger\' }}">\n                                &pound;{{ "%.2f"|format(p.profit) }}\n                            </td>\n                            <td class="{{ \'text-success\' if p.roi > 0 else \'text-danger\' }}">\n                                {{ "%.1f"|format(p.roi) }}%\n                            </td>\n                            <td>{{ r.score }}</td>\n                            <td>{{ r.confidence }}%</td>\n                            <td>\n                                {% if r.recommendation == "BUY" %}\n                                    <span class="badge bg-success">BUY</span>\n                                {% elif r.recommendation == "REVIEW" %}\n                                    <span class="badge bg-warning text-dark">REVIEW</span>\n                                {% else %}\n                                    <span class="badge bg-secondary">IGNORE</span>\n                                {% endif %}\n                            </td>\n                            <td>\n                                <button class="btn btn-sm btn-outline-secondary" type="button" data-bs-toggle="collapse" data-bs-target="#why-{{ loop.index }}">\n                                    <i class="bi bi-info-circle"></i> Why?\n                                </button>\n                            </td>\n                        </tr>\n                        <tr class="collapse" id="why-{{ loop.index }}">\n                            <td colspan="10" class="bg-light">\n                                <div class="row py-2">\n                                    <div class="col-md-6">\n                                        <div class="small text-muted mb-2">\n                                            Trend: price {{ "%+.1f"|format(r.trend.price_change) }}% vs 90d avg,\n                                            offers {{ "%+.1f"|format(r.trend.offer_change) }}%,\n                                            sales rank {{ "%+.1f"|format(r.trend.rank_change) }}%\n                                        </div>\n                                        <h6 class="small fw-bold">Score factors ({{ r.score }}/100)</h6>\n                                        <ul class="list-unstyled small mb-0">\n                                        {% for f in r.score_breakdown %}\n                                            <li class="{{ \'text-success\' if f.passed else \'text-muted\' }}">\n                                                <i class="bi {{ \'bi-check-circle-fill\' if f.passed else \'bi-circle\' }}"></i>\n                                                {{ f.label }}\n                                                {% if f.passed %}<strong>({{ "+" if f.points > 0 else "" }}{{ f.points }})</strong>{% endif %}\n                                            </li>\n                                        {% endfor %}\n                                        </ul>\n                                    </div>\n                                    <div class="col-md-6">\n                                        <h6 class="small fw-bold">Confidence factors ({{ r.confidence }}/100)</h6>\n                                        <ul class="list-unstyled small mb-0">\n                                        {% for f in r.confidence_breakdown %}\n                                            <li class="{{ \'text-danger\' if f.triggered else \'text-success\' }}">\n                                                <i class="bi {{ \'bi-exclamation-triangle-fill\' if f.triggered else \'bi-check-circle-fill\' }}"></i>\n                                                {{ f.label }}\n                                                {% if f.triggered %}<strong>({{ f.points }})</strong>{% endif %}\n                                            </li>\n                                        {% endfor %}\n                                        </ul>\n                                    </div>\n                                </div>\n                            </td>\n                        </tr>\n                        {% endfor %}\n                    </tbody>\n                </table>\n            </div>\n        </div>\n        {% else %}\n            <div class="alert alert-secondary">No viable opportunities found in this batch.</div>\n        {% endif %}\n\n    {% endif %}\n\n{% endif %}\n\n{% endblock %}\n'

with open("app/templates/discovery.html", "w", encoding="utf-8") as f:
    f.write(content)

print("Done -- discovery.html has been rewritten.")